{%- set charge_codes0 = frappe.get_all("Item", filters={"custom_charge_item": 1}, pluck="name") -%}
{%- set cw = {"A": 0.667, "B": 0.667, "C": 0.722, "D": 0.722, "E": 0.667, "F": 0.611, "G": 0.778, "H": 0.722, "I": 0.278, "J": 0.500, "K": 0.667, "L": 0.556, "M": 0.833, "N": 0.722, "O": 0.778, "P": 0.667, "Q": 0.778, "R": 0.722, "S": 0.667, "T": 0.611, "U": 0.722, "V": 0.667, "W": 0.944, "X": 0.667, "Y": 0.667, "Z": 0.611, "a": 0.556, "b": 0.556, "c": 0.500, "d": 0.556, "e": 0.556, "f": 0.278, "g": 0.556, "h": 0.556, "i": 0.222, "j": 0.222, "k": 0.500, "l": 0.222, "m": 0.833, "n": 0.556, "o": 0.556, "p": 0.556, "q": 0.556, "r": 0.333, "s": 0.500, "t": 0.278, "u": 0.556, "v": 0.500, "w": 0.722, "x": 0.500, "y": 0.500, "z": 0.500, " ": 0.278, "-": 0.333, ".": 0.278, ",": 0.278, "/": 0.278, "(": 0.333, ")": 0.333, "&": 0.667, "'": 0.191, "\"": 0.355, ":": 0.278, "+": 0.584, "%": 0.889, "#": 0.556, "*": 0.389, "_": 0.556} -%}
{%- set dd0 = namespace(on=false, line=false) -%}
{%- for it in doc.items -%}{%- if (it.discount_amount or 0) | float > 0.005 or ((it.price_list_rate or 0) | float | abs - (it.rate or 0) | float | abs) > 0.005 -%}{%- set dd0.on = true -%}{%- endif -%}{%- if it.item_code not in charge_codes0 and (it.discount_amount or 0) | float > 0.01 -%}{%- set dd0.line = true -%}{%- endif -%}{%- endfor -%}
{#- Item Name column width in em of its 9pt text: 176pt, or 133pt when the Price List Rate / Discount columns print -#}
{%- set cap = 14.8 if dd0.on else 19.5 -%}
{%- set eh = namespace(items=8.2, chg=0) -%}
{%- for it in doc.items -%}{%- if it.item_code in charge_codes0 -%}{%- set eh.chg = eh.chg + 1 -%}{%- else -%}
{%- set ln = namespace(n=1, w=0) -%}
{%- for word in ((it.item_name or '') | striptags | trim).split() -%}{%- set ww = namespace(v=0) -%}{%- for ch in word -%}{%- set ww.v = ww.v + cw.get(ch, 0.556) -%}{%- endfor -%}
{%- if ln.w == 0 -%}{%- set ln.w = ww.v -%}{%- elif ln.w + 0.278 + ww.v <= cap -%}{%- set ln.w = ln.w + 0.278 + ww.v -%}{%- else -%}{%- set ln.n = ln.n + 1 -%}{%- set ln.w = ww.v -%}{%- endif -%}
{%- if ln.w > cap -%}{%- set ln.n = ln.n + (ln.w / cap) | int -%}{%- set ln.w = ln.w % cap -%}{%- endif -%}
{%- endfor -%}
{%- set eh.items = eh.items + 3.4 + 3.97 * ln.n -%}
{%- endif -%}{%- endfor -%}
{#- totals: one 6.6mm line per tax / charge / discount / round off on the right, or the HSN summary on the left -#}
{%- set tx = namespace(n=0) -%}
{%- for t in (doc.get('taxes') or []) -%}{%- set ta = t.tax_amount_after_discount_amount if t.tax_amount_after_discount_amount is not none else t.tax_amount -%}{%- if ta and (ta > 0.01 or ta < -0.01) -%}{%- set tx.n = tx.n + 1 -%}{%- endif -%}{%- endfor -%}
{%- set n_right = tx.n + eh.chg + (1 if doc.rounding_adjustment and (doc.rounding_adjustment > 0.001 or doc.rounding_adjustment < -0.001) else 0) + (1 if dd0.line else 0) + (1 if (doc.discount_amount or 0) > 0.01 else 0) -%}
{%- set n_hsn = (doc.get('items') or []) | map(attribute='gst_hsn_code') | select | unique | list | length -%}
{%- set totals_h = [23.6 + 6.6 * n_right, 26.2 + 4.6 * n_hsn] | max -%}
{#- header block, left column: 6 address lines and no Delivery At = 47mm; a line over 54 letters wraps -#}
{%- set hl = namespace(a=0, s=0) -%}
{%- for p in (doc.address_display or '').split('<br>') if p | striptags | trim -%}{%- set hl.a = hl.a + 1 + ((p | striptags | trim | length) - 1) // 54 -%}{%- endfor -%}
{%- for p in (doc.shipping_address or '').split('<br>') if p | striptags | trim -%}{%- set hl.s = hl.s + 1 + ((p | striptags | trim | length) - 1) // 54 -%}{%- endfor -%}
{%- set left_h = 47 + 3.9 * (hl.a - 6) + ((4.5 + 3.9 * hl.s) if doc.shipping_address else 0) + (4.5 if (doc.customer_name or '') | length > 45 else 0) + (3.9 if doc.contact_mobile else 0) -%}
{#- right column (Order No / D.C. / Boxes, Due Date / L.R. / Transport / Transporter / e-Way Bill, as Block 3 builds
    it): 18.6 + 6.3 a row, +3.6 a wrapped line (a value wider than 6em in a two-pair row, 22em in a one-pair row) -#}
{%- set dns0 = doc.items | map(attribute='delivery_note') | select | unique | list -%}
{%- set trans0 = (doc.gst_transporter_id or "") ~ (" - " if doc.gst_transporter_id and doc.transporter_name else "") ~ (doc.transporter_name or "") -%}
{%- set rr = namespace(rows=0, extra=0) -%}
{%- for row in [[doc.po_no, doc.po_date], [dns0 | join(" (dd-mm-yy), ") ~ (" (dd-mm-yy)" if dns0 else "")], [doc.custom_no_of_boxes__bundles, doc.due_date], ["L.R.", doc.lr_date], [doc.mode_of_transport, doc.vehicle_no], [doc.custom_transport_details], [trans0], [doc.ewaybill]] -%}
{%- if row | select | list -%}{%- set rr.rows = rr.rows + 1 -%}{%- set mx = namespace(l=1) -%}
{%- for v in row if v -%}{%- set ww = namespace(v=0.556) -%}{%- for ch in (v | string) -%}{%- set ww.v = ww.v + cw.get(ch, 0.556) -%}{%- endfor -%}
{%- set capr = 6.0 if row | length > 1 else 22 -%}{%- set mx.l = [mx.l, ((ww.v / capr) | round(0, 'ceil')) | int] | max -%}{%- endfor -%}
{%- set rr.extra = rr.extra + mx.l - 1 -%}{%- endif -%}{%- endfor -%}
{%- set right_h = 18.6 + 6.3 * rr.rows + 3.6 * rr.extra -%}
{#- e-Invoice strip (IRN, Ack No / Date, QR) under the header: 27mm -#}
{%- set head_h = [left_h, right_h] | max + (27 if doc.irn else 0) -%}
{#- terms block: 53mm (the signature column) up to 8 lines of terms, then 4.2mm a line (95 letters) -#}
{%- set tl = namespace(n=0) -%}
{%- for p in ((doc.terms or '') | replace('</p>', '</li>') | replace('<br>', '</li>')).split('</li>') if p | striptags | trim -%}{%- set tl.n = tl.n + 1 + ((p | striptags | trim | length) - 1) // 95 -%}{%- endfor -%}
{%- set terms_h = 53 + 4.2 * ([tl.n - 8, 0] | max) + 4 * (((doc.remarks or '') | length) // 100) -%}
{#- page height for that content (heading to the last line) in plain flow: 232mm -#}
{%- set dacs_free = 232 - head_h - eh.items - totals_h - terms_h -%}
{#- the blank rows get the space left at the page bottom (less 2.5mm spare), in plain flow — nothing can be squeezed.
    When the content is clearly over a page (12mm) and the terms go to the next page, the blank rows fill
    page 1 down to its bottom instead (a closer call stays plain: the estimate can be a few mm high). Not with notes /
    supplied items (not measured). -#}
{%- set dacs_fill = 0 -%}
{%- if ((doc.get('notes') or '') | striptags | length // 80) <= 0 and ((doc.get('supplied_items') or []) | length) <= 0 -%}
{%- if dacs_free >= 2.5 -%}{%- set dacs_fill = dacs_free - 2.5 -%}
{%- elif dacs_free < -12 and dacs_free + terms_h - 2.5 >= 8 -%}{%- set dacs_fill = dacs_free + terms_h - 2.5 -%}{%- endif -%}
{%- endif -%}
{%- if dacs_fill > 0 %}<style>.dacs-fill-wrap { display: block !important; height: {{ '%.1f' | format(dacs_fill) }}mm; overflow: hidden; }</style>{%- endif %}
{#- Items without the charge lines (Item › Charge item: freight / packing / insurance) — those print
    under the table in the totals; their SAC stays in the GST summary (docs/charges.md). Same columns and
    widths as the builder table this replaces; then a clipped table of blank rows, as tall as
